        foreach ($items as $item) {

            $regionObj = new Region($item);
            unset($regionObj["countries"], $regionObj["pivot"]);
            $regionObj->withoutEvents(function () use ($regionObj) {
                $regionObj->slug = $regionObj::makeSlug($regionObj->name);
                $regionObj->save();
            });

            //pivot continents
            foreach ($item["pivot"] as $key => $synonym) {
                $regionPivotObj = new RegionLanguage([
                    "synonym" => $synonym
                ]);
                $regionPivotObj->region()->associate($regionObj);
                $regionPivotObj->language()->associate(Language::where("slug", "=", $key)->first());
                $regionPivotObj->save();
            };

            if (array_key_exists("countries", $item)) {
                foreach ($item["countries"] as $country) {
                    $countryObj = new Country($country);
                    unset($countryObj["cities"], $countryObj["pivot"]);
                    $countryObj->region()->associate($regionObj);
                    $regionObj->withoutEvents(function () use ($countryObj) {
                        $countryObj->slug = $countryObj::makeSlug($countryObj->name);
                        $countryObj->save();
                    });
                    $regionObj->countries()->save($countryObj);

                    if (array_key_exists("pivot", $country)) {
                        foreach ($country["pivot"] as $key => $synonym) {
                            $countryPivotObj = new CountryLanguage([
                                "synonym" => $synonym
                            ]);
                            $countryPivotObj->country()->associate($countryObj);
                            $countryPivotObj->language()->associate(Language::where("slug", "=", $key)->first());
                            $countryPivotObj->save();
                        };
                    }

                    // Cities
                    if (array_key_exists("cities", $country)) {
                        foreach ($country["cities"] as $city) {

                            $cityObj = new City($city);
                            $cityObj->country()->associate($countryObj);
                            $cityObj->withoutEvents(function () use ($cityObj) {
                                $cityObj->slug = $cityObj::makeSlug($cityObj->name);
                                $cityObj->save();
                            });
                            $cityObj->save();

                            // cities pivot
                            if (array_key_exists("pivot", $city)) {
                                foreach ($city["pivot"] as $key => $synonym) {
                                    $cityPivotObj = new CityLanguage([
                                        "synonym" => $synonym
                                    ]);
                                    $cityPivotObj->country()->associate($cityObj);
                                    $cityPivotObj->language()->associate(Language::where("slug", "=", $key)->first());
                                    $cityPivotObj->save();
                                }
                            }
                        }
                    }
                }
            }

